insert into public.products (id, slug, name, short_description, description, category_id, price_kobo, compare_at_kobo, sku, tags, image_badge, image_badge_style, image_badge_icon, perk_text, perk_icon, perk_style, delivery_note, delivery_note_icon, pod_available, warranty_months, specs, curated_rank, curated_label, seo_title, seo_description, created_at) values ('c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', 'turbo-car-vacuum', '4-in-1 Turbo Cordless Car Vacuum & Blower', 'Vacuum, blow, inflate & deflate — 9,000Pa cordless jet power for car and home.', 'Blow stubborn AC sand, pull deep coin crumbs and inflate car tyres in 60 seconds with the MUBAZZAR 4-in-1 Turbo Cordless Handheld Jet Vacuum. Built for dusty harmattan seasons, roadside sand and everyday quick interior touch-ups.', '12c56602-4564-5b8d-8a8f-433ded8fad3b', 2450000, null, 'MBZ-TURBO-CAR-VACUUM', array['vacuum', 'car', 'blower', 'inflator', 'cordless', 'cleaning']::text[], '9,000Pa Suction', 'navy', 'tornado', null, null, 'gold', 'Lagos 24h Delivery', 'local_shipping', true, 12, '[{"label":"Suction power","value":"9,000Pa turbo vortex"},{"label":"Battery","value":"Dual 2,000mAh lithium cells"},{"label":"Runtime","value":"Up to 45 minutes"},{"label":"Charging","value":"USB Type-C, ~2 hours"},{"label":"Filter","value":"Washable dual HEPA"},{"label":"Modes","value":"Vacuum · Blow · Inflate · Deflate"}]'::jsonb, null, null, '4-in-1 Turbo Cordless Car Vacuum & Blower | MUBAZZAR', 'Vacuum, blow, inflate & deflate — 9,000Pa cordless jet power for car and home.', now() - interval '20 days');
insert into public.product_images (id, product_id, url, alt, sort_order) values ('bd96de04-7100-54ad-82fc-a699676257c4', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', '/images/products/car-vacuum-hero.webp', 'MUBAZZAR 4-in-1 cordless handheld car vacuum suctioning sand and crumbs from leather car seats', 0);
insert into public.product_images (id, product_id, url, alt, sort_order) values ('b92ae74f-a488-5c26-bc00-24fead9248c1', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', '/images/products/car-vacuum-1.webp', 'Handheld cordless vacuum cleaning crumbs and fine red sand from an SUV floor mat', 1);
insert into public.product_images (id, product_id, url, alt, sort_order) values ('d3cdbfc9-4d86-5674-914c-922c5be5b454', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', '/images/products/car-vacuum-2.webp', 'Reverse blow nozzle blasting dust out of a car AC dashboard vent', 2);
insert into public.product_images (id, product_id, url, alt, sort_order) values ('3fd60400-9ff8-5b97-86b3-f9d42ad4bd4d', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', '/images/products/car-vacuum-3.webp', 'Turbo blower inflating a swimming float with the cone nozzle', 3);
insert into public.product_images (id, product_id, url, alt, sort_order) values ('23603073-315b-53d3-84b5-1bc438a0503f', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', '/images/products/car-vacuum-4.webp', 'Washable steel and HEPA double filter rinsed under running tap water', 4);
insert into public.product_images (id, product_id, url, alt, sort_order) values ('831741ed-0edf-57ee-b3a3-d6a15a7de7ce', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', '/images/products/car-vacuum-5.webp', 'Unboxed package: navy box, Type-C cable, 4 nozzle heads, extra HEPA filter and pouch', 5);
insert into public.product_features (id, product_id, icon, title, description, sort_order) values ('c7793da6-33e5-5b8d-bd7c-9f5097ab093a', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', 'tornado', 'Extreme 9,000Pa Suction Power', 'Lifts heavy coins, spilled groundnuts, pet hair, and coarse street sand trapped deep inside carpet fibers effortlessly.', 0);
insert into public.product_features (id, product_id, icon, title, description, sort_order) values ('8e406a06-8777-507f-9ae6-3b7e29bf3753', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', 'air', 'Reverse High-Pressure Blower', 'Flip it over to blast hidden dust from deep AC vents, steering column crevices, laptop keyboards, or light your weekend BBQ grill.', 1);
insert into public.product_features (id, product_id, icon, title, description, sort_order) values ('ad9f91da-f2b5-5f20-9454-f15e5032efb0', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', 'battery_charging_full', 'Heavy-Duty Type-C Fast Charging', 'Dual 2,000mAh lithium cells give 45 minutes of continuous cordless cleaning. Power it up directly from your car cigarette lighter adapter or powerbank.', 2);
insert into public.product_features (id, product_id, icon, title, description, sort_order) values ('6afd21fd-a577-5721-9102-5ebb210425cd', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', 'water_drop', 'Washable Dual HEPA Filter', 'No costly refills. Simply rinse with tap water, dry, and snap back. Captures 99.9% of micro dust mites and allergens.', 3);
insert into public.product_features (id, product_id, icon, title, description, sort_order) values ('80baca07-2ac8-5f25-9a75-b2e947367794', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', 'sports_volleyball', 'Inflator & Deflator Pump Mode', 'Includes custom nozzles to pump party balloons, swimming rings, and air mattresses, or vacuum-seal storage bags for luggage space.', 4);
insert into public.product_faqs (id, product_id, question, answer, sort_order) values ('a542872f-02ec-5233-9741-fc2e1c15600a', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', 'How long does delivery take to my state?', 'Orders within Lagos and Abuja placed before the daily cut-off can arrive the same day; otherwise next day. Port Harcourt, Ibadan, Benin, Kano, Enugu and all other states take 2 to 4 working days via our partner dispatch fleet. Your exact fee and ETA show in the order form when you pick your state.', 0);
insert into public.product_faqs (id, product_id, question, answer, sort_order) values ('7595d52b-baa5-5376-863b-d79bcf9a47de', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', 'Can I really open and check it before paying?', 'Yes. If you agree Pay on Delivery with our team on WhatsApp, you can unseal the outer carton and switch the vacuum on to feel the suction and blower power before paying the rider by cash, POS or transfer.', 1);
insert into public.product_faqs (id, product_id, question, answer, sort_order) values ('2bd4f105-ff52-51c6-aebc-a98befd92fa9', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', 'What is inside the complete package?', 'Every set includes: 1x MUBAZZAR 4-in-1 Turbo Handheld Device, 1x long flat crevice nozzle, 1x brush head for seat carpets, 1x reverse air-blow jet tip, 1x air inflator nozzle, 1x washable HEPA filter (plus an extra free bonus filter), 1x Type-C charging cable, user manual, plus your free Aromatherapy Car Diffuser while the promo runs.', 2);
insert into public.product_faqs (id, product_id, question, answer, sort_order) values ('3a84fdff-a8cb-538e-b0f8-471fe2abfdf7', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', 'How do I charge it? Can I use my car charger?', 'Yes. It has a universal Type-C port, so you can charge it from your car USB port/adapter, any phone charger or a power bank. A full charge takes about 2 hours and lasts up to 45 minutes of cleaning.', 3);
