insert into public.product_faqs (id, product_id, question, answer, sort_order) values ('ad8a9858-2cbc-59ac-87b0-c891ef94a9ff', 'ffb84f98-73eb-5113-b386-a5e7f79dad19', 'How do I pay?', 'Place your order on this page, then tap “Complete Payment on WhatsApp”. Our team confirms your order in chat and shares MUBAZZAR''s official payment details. Pay on Delivery can be arranged in chat. We never ask for card PINs or OTPs.', 0);
insert into public.product_faqs (id, product_id, question, answer, sort_order) values ('669fe2f7-e324-5cf0-8823-149b75dc6db2', 'ffb84f98-73eb-5113-b386-a5e7f79dad19', 'How long will delivery take?', 'Lagos and Abuja orders placed before the daily cut-off can arrive the same day. Other states take 2–4 working days. Your exact fee and delivery time show when you choose your state.', 1);
insert into public.product_faqs (id, product_id, question, answer, sort_order) values ('4242c362-35ed-51e6-aff9-049b2801d520', 'ffb84f98-73eb-5113-b386-a5e7f79dad19', 'What if it arrives faulty?', 'Every item is tested before dispatch. If anything is defective, message us within 7 days for a free swap or refund.', 2);
