insert into public.landing_pages (id, slug, product_id, is_published, hook_label, hook_banner, trend_badge, headline, subheadline, hero_overlay_text, hero_overlay_icon, warranty_badge, regions_text, campaign_ends_at, features_title, features_subtitle, video_url, video_poster_url, video_title, video_subtitle, cta_label, seo_title, seo_description, og_image_url) values ('170522c1-1549-56c2-b620-972c12e56ceb', 'car-vacuum', 'c22186f5-66a6-5e38-b65b-9f56aa0dd5c4', true, 'PROMO ALERT', '⚡ Promo price + Free Luxury Car Diffuser | Pay on Delivery available — arrange in chat', 'Tested by our Lagos team', 'Stop Paying Car Wash ~~₦4,000~~ Every Week!', 'Blow stubborn AC sand, pull deep coin crumbs, and inflate car tires in 60 seconds with the **Mubazzar 4-in-1 Turbo Cordless Handheld Jet Vacuum**.', '9,000Pa Turbo Vortex Engine', 'electric_meter', '1-Year Warranty', 'Lagos • Abuja • PH • Kano', date_trunc('day', now() at time zone 'UTC') at time zone 'UTC' + interval '3 days' - interval '1 hour', 'Why Nigerian Drivers Love This 4-in-1 Beast', 'Designed to handle dusty dry harmattan seasons, roadside potholes sand, and everyday quick interior touchups.', null, '/images/products/vacuum-demo.webp', 'See It Lift Coins & Sand', 'Real demo inside a Nigerian car', 'Place Order & Pay on WhatsApp', '4-in-1 Turbo Cordless Car Vacuum — Pay on Delivery | MUBAZZAR', 'Vacuum, blow, inflate and deflate with one cordless 9,000Pa device. Same-day delivery in Lagos & Abuja, nationwide in 2–4 days. Order now and pay on WhatsApp.', '/images/products/car-vacuum-hero.webp');
insert into public.landing_page_sections (id, landing_page_id, kind, title, items, sort_order) values ('fb823a2e-f8a7-554b-a09c-0b0b8a7366af', '170522c1-1549-56c2-b620-972c12e56ceb', 'trust_matrix', 'Shop With Zero Risk', '[{"icon":"payments","title":"Pay On Delivery (Arrange in Chat)","body":"Agree Pay on Delivery with our team on WhatsApp, then inspect and test before paying the rider by cash, POS or transfer."},{"icon":"rocket_launch","title":"Express Delivery Time","body":"Same-day in Lagos & Abuja before the daily cut-off. 2 to 4 working days across all 36 states."},{"icon":"verified_user","title":"12 Months Mubazzar Warranty","body":"Any factory fault? We replace it completely free with no hassle."}]'::jsonb, 1);
